        this.addAnnotation((ENamedElement)this.itemLabelPosEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "The label is rendered in a new line if it is longer than the indentation.\r\n"});
        this.addAnnotation((ENamedElement)this.itemLabelPosEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "The label is rendered in one line with the item even if it is longer than the indentation.\r\n"});
